```java
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Set;
import org.apache.commons.io.serialization.ValidatingObjectInputStream;

public class SecureServer {
    public static void main(String[] args) throws IOException {
        ServerSocket server = new ServerSocket(8080);
        System.out.println("Secure server listening on 8080...");

        // Define a whitelist of allowed classes to prevent arbitrary code execution
        Set<String> allowedClasses = Set.of("java.lang.String", "com.myapp.MySafeData");

        while (true) {
            try (Socket socket = server.accept();
                 InputStream is = socket.getInputStream()) {

                // Use a ValidatingObjectInputStream to restrict deserialization 
                // only to known, safe classes.
                ValidatingObjectInputStream vois = new ValidatingObjectInputStream(is);
                vois.accept(allowedClasses.toArray(new String[0]));

                Object obj = vois.readObject();
                System.out.println("Received: " + obj.toString());

            } catch (Exception e) {
                System.err.println("Blocked attempt or error: " + e.getMessage());
            }
        }
    }
}
```

